using System;
using System.Collections.Generic;
using System.Text;
using UnityEngine;

namespace Ankhu.Realms
{
    /// <summary>
    /// Gardiner code to hieroglyph sprite, plus the frame, particle and bubble textures of the words of power.
    /// Textures live in Art/Glyphs/Resources/RealmGlyphs (generated by Art/Glyphs/_tools/make_glyphs.py from
    /// Noto Sans Egyptian Hieroglyphs). Sprites are made at runtime with Sprite.Create, so the PNG import type
    /// does not matter and the textures need not be readable. Every glyph texture shares one em box
    /// (<see cref="GlyphTable.EmPixels"/> tall, common baseline), so signs keep their relative size and place.
    /// Codes are matched without regard to case or leading zeros ("aa1", "E034" and "E34" all work).
    /// </summary>
    public static class GlyphAtlas
    {
        public const string ResourceFolder = "RealmGlyphs/";
        private const float PixelsPerUnit = 100f;

        private static Dictionary<string, GlyphInfo> infos;
        private static readonly Dictionary<string, Sprite> sprites = new Dictionary<string, Sprite>();
        private static readonly Dictionary<string, Texture2D> textures = new Dictionary<string, Texture2D>();
        private static readonly HashSet<string> warned = new HashSet<string>();

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetStatics()
        {
            sprites.Clear();
            textures.Clear();
            warned.Clear();
        }

        // ------------------------------------------------------------------ codes

        /// <summary>Canonical Gardiner spelling ("aa001" becomes "Aa1", "n035a" becomes "N35A"). Null for blank input.</summary>
        public static string Normalize(string code)
        {
            if (string.IsNullOrWhiteSpace(code)) return null;
            string c = code.Trim();
            int i = 0;
            var sb = new StringBuilder(c.Length);
            while (i < c.Length && char.IsLetter(c[i]))
            {
                sb.Append(sb.Length == 0 ? char.ToUpperInvariant(c[i]) : char.ToLowerInvariant(c[i]));
                i++;
            }
            int digitsStart = i;
            while (i < c.Length && char.IsDigit(c[i])) i++;
            if (i > digitsStart)
            {
                string digits = c.Substring(digitsStart, i - digitsStart).TrimStart('0');
                sb.Append(digits.Length == 0 ? "0" : digits);
            }
            for (; i < c.Length; i++) sb.Append(char.ToUpperInvariant(c[i]));
            return sb.ToString();
        }

        private static Dictionary<string, GlyphInfo> Infos
        {
            get
            {
                if (infos != null) return infos;
                infos = new Dictionary<string, GlyphInfo>(StringComparer.Ordinal);
                foreach (GlyphInfo g in GlyphTable.All) infos[g.Code] = g;
                return infos;
            }
        }

        /// <summary>Every Gardiner code that ships with a texture.</summary>
        public static IEnumerable<string> Codes => Infos.Keys;

        /// <summary>True when the sign is in the table (its texture ships under Resources).</summary>
        public static bool Has(string code)
        {
            string key = Normalize(code);
            return key != null && Infos.ContainsKey(key);
        }

        public static bool TryGetInfo(string code, out GlyphInfo info)
        {
            string key = Normalize(code);
            if (key != null && Infos.TryGetValue(key, out info)) return true;
            info = default;
            return false;
        }

        /// <summary>The sign as Unicode text (for fonts that have the Egyptian block), or null.</summary>
        public static string UnicodeOf(string code) => TryGetInfo(code, out GlyphInfo g) ? g.Text : null;

        // ------------------------------------------------------------------ glyph sprites

        /// <summary>White sign on transparent, full em box, pivot centre. Null if missing.</summary>
        public static Sprite Get(string code) => GlyphSprite(code, false);

        /// <summary>Blurred halo of the sign, same size and pivot as <see cref="Get"/>. Null if missing.</summary>
        public static Sprite GetGlow(string code) => GlyphSprite(code, true);

        public static Texture2D GetTexture(string code)
        {
            string key = Normalize(code);
            return key != null && Infos.ContainsKey(key) ? LoadTexture(key) : null;
        }

        public static Texture2D GetGlowTexture(string code)
        {
            string key = Normalize(code);
            return key != null && Infos.ContainsKey(key) ? LoadTexture(key + "_glow") : null;
        }

        /// <summary>Ink box of a sign inside its em box, normalised, y up (x = left, y = bottom).</summary>
        public static Rect InkRect(string code)
        {
            if (!TryGetInfo(code, out GlyphInfo g)) return new Rect(0.1f, 0.1f, 0.8f, 0.8f);
            return Rect.MinMaxRect(g.InkLeft, g.InkBottom, g.InkRight, g.InkTop);
        }

        /// <summary>Texture width over height (1 or 2 for the shipped signs).</summary>
        public static float Aspect(string code)
        {
            if (!TryGetInfo(code, out GlyphInfo g) || g.Height == 0) return 1f;
            return g.Width / (float)g.Height;
        }

        private static Sprite GlyphSprite(string code, bool glow)
        {
            string key = Normalize(code);
            if (key == null) return null;
            if (!Infos.ContainsKey(key))
            {
                if (warned.Add(key)) Debug.LogWarning("[Ankhu.Realms] No hieroglyph for Gardiner code '" + code + "'.");
                return null;
            }
            return SpriteFor(glow ? key + "_glow" : key, Vector4.zero);
        }

        // ------------------------------------------------------------------ frames, particles, UI pieces

        /// <summary>Horizontal cartouche: rope oval tied off by a bar at the right. 9 sliced, see <see cref="GlyphTable.CartoucheBorder"/>.</summary>
        public static Sprite Cartouche => SpriteFor("cartouche", GlyphTable.CartoucheBorder);
        public static Sprite CartoucheGlow => SpriteFor("cartouche_glow", GlyphTable.CartoucheBorder);

        public static Texture2D Mote => Fx("fx_mote");
        public static Texture2D Spark => Fx("fx_spark");
        public static Texture2D Ring => Fx("fx_ring");
        public static Texture2D Smoke => Fx("fx_smoke");
        public static Texture2D Flare => Fx("fx_flare");
        public static Texture2D Shaft => Fx("fx_shaft");
        public static Texture2D Grain => Fx("fx_grain");

        public static Sprite MoteSprite => SpriteFor("fx_mote", Vector4.zero);
        public static Sprite SparkSprite => SpriteFor("fx_spark", Vector4.zero);
        public static Sprite GrainSprite => SpriteFor("fx_grain", Vector4.zero);
        public static Sprite FlareSprite => SpriteFor("fx_flare", Vector4.zero);

        /// <summary>Rounded rectangle fill, 9 sliced (corner radius 24 px on a 128 px texture).</summary>
        public static Sprite UiPanel => SpriteFor("ui_panel", new Vector4(28, 28, 28, 28));
        /// <summary>Rounded rectangle hairline, same geometry as <see cref="UiPanel"/>.</summary>
        public static Sprite UiBorder => SpriteFor("ui_border", new Vector4(28, 28, 28, 28));
        /// <summary>Soft shadow for the panel, 9 sliced, the solid part starts 48 px in.</summary>
        public static Sprite UiShadow => SpriteFor("ui_shadow", new Vector4(96, 96, 96, 96));
        public static Sprite UiTail => SpriteFor("ui_tail", Vector4.zero);
        public static Sprite UiSheen => SpriteFor("ui_sheen", Vector4.zero);
        public static Sprite UiHairline => SpriteFor("ui_hairline", Vector4.zero);

        /// <summary>Painted skin: torn papyrus sheet, 9 sliced at 72 px (512x256 texture).</summary>
        public static Sprite UiPapyrus => SpriteFor("ui_papyrus", new Vector4(72, 72, 72, 72));
        /// <summary>Painted skin: red ochre and carbon ruled border, transparent centre, same slicing as <see cref="UiPapyrus"/>.</summary>
        public static Sprite UiPapyrusFrame => SpriteFor("ui_papyrus_frame", new Vector4(72, 72, 72, 72));
        public static Sprite UiPapyrusTail => SpriteFor("ui_papyrus_tail", Vector4.zero);
        public static Sprite UiPapyrusTailInk => SpriteFor("ui_papyrus_tail_ink", Vector4.zero);
        public static Sprite UiInkCaret => SpriteFor("ui_ink_caret", Vector4.zero);

        /// <summary>True when Resources holds the named texture (no warning, no fallback dot).</summary>
        public static bool HasResource(string name)
        {
            if (textures.TryGetValue(name, out Texture2D t) && t != null && t != softDot) return true;
            return Resources.Load<Texture2D>(ResourceFolder + name) != null;
        }

        private static Texture2D Fx(string name) => LoadTexture(name);

        private static Sprite SpriteFor(string name, Vector4 border)
        {
            if (sprites.TryGetValue(name, out Sprite s) && s != null) return s;
            Texture2D tex = LoadTexture(name);
            if (tex == null) return null;
            // Borders are authored in source pixels. Scale them if Unity resized the texture on import.
            Vector4 b = border;
            if (b != Vector4.zero)
            {
                float k = tex.height / (float)SourceHeight(name, tex.height);
                b *= k;
                b.x = Mathf.Min(b.x, tex.width * 0.49f); b.z = Mathf.Min(b.z, tex.width * 0.49f);
                b.y = Mathf.Min(b.y, tex.height * 0.49f); b.w = Mathf.Min(b.w, tex.height * 0.49f);
            }
            s = Sprite.Create(tex, new Rect(0f, 0f, tex.width, tex.height), new Vector2(0.5f, 0.5f), PixelsPerUnit, 0,
                SpriteMeshType.FullRect, b);
            s.name = name;
            s.hideFlags = HideFlags.DontSave;
            sprites[name] = s;
            return s;
        }

        private static int SourceHeight(string name, int fallback)
        {
            switch (name)
            {
                case "cartouche":
                case "cartouche_glow":
                case "ui_shadow": return 256;
                case "ui_panel":
                case "ui_border": return 128;
                case "ui_papyrus":
                case "ui_papyrus_frame": return 256;
                default: return fallback;
            }
        }

        private static Texture2D LoadTexture(string name)
        {
            if (textures.TryGetValue(name, out Texture2D t) && t != null) return t;
            t = Resources.Load<Texture2D>(ResourceFolder + name);
            if (t == null)
            {
                if (warned.Add("tex:" + name)) Debug.LogWarning("[Ankhu.Realms] Missing Resources/" + ResourceFolder + name + ".png, using a soft dot.");
                t = SoftDot();
            }
            else
            {
                t.wrapMode = TextureWrapMode.Clamp;
                if (t.filterMode == FilterMode.Point) t.filterMode = FilterMode.Bilinear;
            }
            textures[name] = t;
            return t;
        }

        private static Texture2D softDot;

        private static Texture2D SoftDot()
        {
            if (softDot != null) return softDot;
            softDot = Ankhu.Opening.UiKit.SoftDot(64, 2f);
            softDot.hideFlags = HideFlags.DontSave;
            return softDot;
        }
    }
}
